def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Report_Categories.csv'
    # Try common encodings for CSVs exported from Excel/Windows
    for enc in ['utf-8-sig', 'cp1252', 'latin1']:
        try:
            df = pd.read_csv(path, encoding=enc)
            df['_encoding_used'] = enc
            return pd.concat([df.head(5), df.tail(5)], ignore_index=True)
        except UnicodeDecodeError:
            continue
    # Fallback with replacement to at least inspect structure
    df = pd.read_csv(path, encoding='latin1')
    df['_encoding_used'] = 'latin1'
    return pd.concat([df.head(5), df.tail(5)], ignore_index=True)

def load() -> pd.DataFrame:
    import pandas as pd
    encodings = ['utf-8-sig','cp1252','latin1']
    path = 'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Report_Categories.csv'
    last_err=None
    for enc in encodings:
        try:
            df = pd.read_csv(path, encoding=enc)
            df['_encoding_used']=enc
            return df
        except Exception as e:
            last_err=e
    raise last_err
